import { useState, useEffect, useCallback } from "react";

const AC="#38bdf8",AP="#a78bfa",AE="#34d399",AO="#fb923c",AR="#fb7185",AA="#fbbf24";
const BD="#0f172a",BC="#1e293b";

const IMG_HOME="data:image/jpeg;base64,";
const IMG_CK="data:image/jpeg;base64,";
const IMG_S1="data:image/jpeg;base64,";
const IMG_S2="data:image/jpeg;base64,";
const IMG_S3="data:image/jpeg;base64,";
const SLIDES_IMG=[IMG_S1, IMG_S2, IMG_S3];

const OUTPUTS=[
  {icon:"🎬",label:"5 Clips",color:"#ef4444"},
  {icon:"🧵",label:"3 Carousels",color:AC},
  {icon:"📝",label:"7 Posts",color:AP},
  {icon:"📅",label:"Calendar",color:AE},
];

const KB_SOURCES=[
  {icon:"▶️",label:"YouTube",color:"#ef4444"},
  {icon:"📝",label:"Blogs",color:"#f59e0b"},
  {icon:"✉️",label:"Emails",color:"#8b5cf6"},
  {icon:"🎙️",label:"Voice",color:AC},
];

const STEPS=["Transcribing audio...","Identifying key moments...","Matching your voice...","Generating content kit..."];

const CAL_DAYS=["M","T","W","T","F","S","S"];
const CAL_DATA=[
  [1,0,2,3,0,1,0],
  [3,2,0,1,3,0,2],
  [0,1,3,0,2,1,0],
];
const CAL_ICONS=["","🎬","🧵","📝","🎙️"];
const CAL_COLORS=["","#ef4444",AC,AP,AE];

/* ============ SUB-COMPONENTS ============ */

function PhaseLabel({text,sub,visible,color=AC}){
  return(
    <div style={{position:"absolute",top:"30px",left:"50%",transform:"translateX(-50%)",textAlign:"center",opacity:visible?1:0,transition:"all 0.5s ease",zIndex:200,pointerEvents:"none"}}>
      <div style={{display:"inline-flex",alignItems:"center",gap:"6px",background:`${color}15`,border:`1px solid ${color}30`,borderRadius:"20px",padding:"5px 14px",fontSize:"11px",color,letterSpacing:"0.5px",marginBottom:"8px"}}>{sub}</div>
      <h2 style={{fontSize:"24px",fontWeight:300,color:"#e2e8f0",margin:"6px 0 0",letterSpacing:"-0.5px"}}>{text}</h2>
    </div>
  );
}

function ProgressBar({progress,visible}){
  return(
    <div style={{width:"240px",height:"5px",background:`${AC}15`,borderRadius:"3px",overflow:"hidden",opacity:visible?1:0,transition:"opacity 0.3s ease"}}>
      <div style={{width:`${progress}%`,height:"100%",background:`linear-gradient(90deg,${AC},${AP})`,borderRadius:"3px",transition:"width 0.3s ease"}}/>
    </div>
  );
}

function OutputCard({item,index,visible,total}){
  const angle=((index-(total-1)/2)/total)*1.1;
  const fx=Math.sin(angle)*180,fy=Math.cos(angle)*-30+index*4;
  return(
    <div style={{position:"absolute",left:"50%",top:"50%",transform:visible?`translate(calc(-50% + ${fx}px),calc(-50% + ${fy}px)) scale(1)`:"translate(-50%,-50%) scale(0)",opacity:visible?1:0,transition:`all 0.6s cubic-bezier(0.34,1.56,0.64,1) ${0.05+index*0.1}s`,zIndex:20}}>
      <div style={{width:"100px",padding:"12px 8px",background:`${item.color}10`,border:`1.5px solid ${item.color}40`,borderRadius:"14px",textAlign:"center"}}>
        <div style={{fontSize:"22px",marginBottom:"3px"}}>{item.icon}</div>
        <div style={{fontSize:"12px",fontWeight:700,color:item.color}}>{item.label}</div>
      </div>
    </div>
  );
}

function SlideCard({img,index,total,visible}){
  const fanAngle=(index-(total-1)/2)*12;
  const fx=(index-(total-1)/2)*80;
  const fy=Math.abs(index-(total-1)/2)*8;
  return(
    <div style={{position:"absolute",left:"50%",top:"50%",marginLeft:"-90px",marginTop:"-90px",width:"180px",height:"180px",borderRadius:"12px",overflow:"hidden",transform:visible?`translateX(${fx}px) translateY(${fy}px) rotate(${fanAngle}deg) scale(0.9)`:"translate(0,0) scale(0)",opacity:visible?1:0,zIndex:total-Math.abs(index-1),transition:`all 0.7s cubic-bezier(0.34,1.56,0.64,1) ${index*0.1}s`,boxShadow:`0 8px 30px rgba(0,0,0,0.4),0 0 20px ${AC}15`}}>
      <img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>
    </div>
  );
}

function KBNode({source,index,visible,total}){
  const angle=(index/total)*Math.PI*2-Math.PI/2;
  const r=visible?100:0;
  const x=Math.cos(angle)*r,y=Math.sin(angle)*r;
  return(
    <div style={{position:"absolute",left:"50%",top:"50%",transform:`translate(calc(-50% + ${x}px),calc(-50% + ${y}px)) scale(${visible?1:0})`,transition:`all 0.6s cubic-bezier(0.34,1.56,0.64,1) ${index*0.1}s`,opacity:visible?1:0,zIndex:10}}>
      <div style={{width:"56px",height:"56px",borderRadius:"14px",background:`${source.color}15`,border:`1.5px solid ${source.color}40`,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:"1px"}}>
        <span style={{fontSize:"18px"}}>{source.icon}</span>
        <span style={{fontSize:"7px",color:source.color,fontWeight:600}}>{source.label}</span>
      </div>
    </div>
  );
}

function MiniCal({visible,revealCount}){
  return(
    <div style={{opacity:visible?1:0,transform:visible?"scale(1)":"scale(0.8)",transition:"all 0.5s ease"}}>
      <div style={{display:"flex",gap:"4px",marginBottom:"3px"}}>
        {CAL_DAYS.map((d,i)=><div key={i} style={{width:"36px",textAlign:"center",fontSize:"7px",fontWeight:600,color:"#475569",textTransform:"uppercase"}}>{d}</div>)}
      </div>
      {CAL_DATA.map((week,wi)=>(
        <div key={wi} style={{display:"flex",gap:"4px",marginBottom:"4px"}}>
          {week.map((cell,ci)=>{
            const idx=wi*7+ci;
            const shown=idx<revealCount&&cell>0;
            return(
              <div key={ci} style={{width:"36px",height:"36px",borderRadius:"8px",background:shown?`${CAL_COLORS[cell]}10`:`${BD}60`,border:`1px solid ${shown?CAL_COLORS[cell]+"40":"#1e293b30"}`,display:"flex",alignItems:"center",justifyContent:"center",transition:`all 0.3s ease ${idx*0.03}s`,opacity:shown?1:cell>0?0.15:0.3}}>
                {cell>0&&<span style={{fontSize:shown?"14px":"8px",transition:"all 0.3s ease",filter:shown?"none":"grayscale(1)"}}>{CAL_ICONS[cell]}</span>}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

function ScreenshotFrame({src,visible,delay=0,width=220,x=0,y=0,borderColor=AC}){
  return(
    <div style={{position:"absolute",left:"50%",top:"50%",transform:`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`,opacity:visible?1:0,transition:`all 0.6s cubic-bezier(0.34,1.56,0.64,1) ${delay}s`,zIndex:30,pointerEvents:"none"}}>
      <div style={{width:`${width}px`,borderRadius:"12px",overflow:"hidden",boxShadow:`0 10px 40px rgba(0,0,0,0.5),0 0 24px ${borderColor}20`,border:`1.5px solid ${borderColor}40`}}>
        <img src={src} alt="" style={{width:"100%",display:"block"}}/>
      </div>
    </div>
  );
}

function CreatorBadge({visible}){
  return(
    <div style={{display:"inline-flex",alignItems:"center",gap:"10px",background:`linear-gradient(135deg,${AA}12,${AC}12)`,border:`1px solid ${AA}30`,borderRadius:"20px",padding:"8px 18px",opacity:visible?1:0,transform:visible?"translateY(0)":"translateY(15px)",transition:"all 0.6s ease"}}>
      <span style={{fontSize:"13px",fontWeight:600,color:AA}}>Their Ideas.</span>
      <span style={{fontSize:"16px"}}>→</span>
      <span style={{fontSize:"13px",fontWeight:600,color:AC}}>Your Voice.</span>
    </div>
  );
}

/* ============ MASTER COMPONENT ============ */

export default function EchoMeMasterDemo(){
  const[phase,setPhase]=useState("idle");
  const[progress,setProgress]=useState(0);
  const[stepIdx,setStepIdx]=useState(0);
  const[calReveal,setCalReveal]=useState(0);

  const wait=useCallback((ms)=>new Promise(r=>setTimeout(r,ms)),[]);

  useEffect(()=>{
    let cancelled=false;
    const run=async()=>{
      if(cancelled) return;

      // 1. UPLOAD
      setPhase("upload");setProgress(0);setStepIdx(0);setCalReveal(0);
      await wait(1500);

      // 2. PROCESSING
      if(cancelled) return;
      setPhase("processing");
      for(let i=0;i<=100;i+=3){
        if(cancelled) return;
        setProgress(i);
        if(i>0&&i%25===0) setStepIdx(Math.min(Math.floor(i/25),STEPS.length-1));
        await wait(40);
      }
      await wait(400);

      // 3. KNOWLEDGE BASE FLASH
      if(cancelled) return;
      setPhase("kb");
      await wait(2200);

      // 4. SCREENSHOT SHOWCASE
      if(cancelled) return;
      setPhase("screenshots");
      await wait(3000);

      // 5. CONTENT KIT EXPLOSION
      if(cancelled) return;
      setPhase("outputs");
      await wait(2500);

      // 6. CAROUSEL FAN
      if(cancelled) return;
      setPhase("carousels");
      await wait(3000);

      // 7. CALENDAR POPULATE
      if(cancelled) return;
      setPhase("calendar");
      for(let i=0;i<=21;i++){
        if(cancelled) return;
        setCalReveal(i);
        await wait(80);
      }
      await wait(1500);

      // 8. CREATOR REPURPOSING TEASE
      if(cancelled) return;
      setPhase("repurpose");
      await wait(2500);

      // 9. CTA
      if(cancelled) return;
      setPhase("cta");
      await wait(3000);

      // RESET
      if(cancelled) return;
      setPhase("idle");
      await wait(800);
      if(!cancelled) run();
    };
    run();
    return()=>{cancelled=true;};
  },[wait]);

  const isProc=phase==="processing";

  return(
    <div style={{width:"100%",height:"100vh",background:`radial-gradient(ellipse at 50% 35%,${BC},${BD} 70%)`,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontFamily:"system-ui,sans-serif",overflow:"hidden",position:"relative"}}>
      <style>{`
        @keyframes uploadBounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
        @keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
        @keyframes corePulse{0%,100%{box-shadow:0 0 15px ${AC}15}50%{box-shadow:0 0 40px ${AC}40,0 0 60px ${AP}15}}
        @keyframes fadeInUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
      `}</style>

      {/* Subtle grid */}
      <div style={{position:"absolute",inset:0,backgroundImage:`linear-gradient(${AC}06 1px,transparent 1px),linear-gradient(90deg,${AC}06 1px,transparent 1px)`,backgroundSize:"60px 60px"}}/>

      {/* PHASE LABELS */}
      <PhaseLabel text={<>Upload a Video. <span style={{background:`linear-gradient(135deg,${AO},${AC})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Get a Content Kit.</span></>} sub="⚡ The Engine" visible={phase==="upload"||phase==="processing"} color={AO}/>
      <PhaseLabel text={<>Knowledge <span style={{background:`linear-gradient(135deg,${AE},${AC})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Base</span></>} sub="🧠 Your Voice DNA" visible={phase==="kb"} color={AE}/>
      <PhaseLabel text={<>Real Product. <span style={{background:`linear-gradient(135deg,${AC},${AP})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Real Output.</span></>} sub="📸 See It Working" visible={phase==="screenshots"} color={AC}/>
      <PhaseLabel text={<>Your <span style={{background:`linear-gradient(135deg,${AC},${AP})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Content Kit</span></>} sub="📦 One Upload →" visible={phase==="outputs"} color={AC}/>
      <PhaseLabel text={<>Tweet-Style <span style={{background:`linear-gradient(135deg,${AC},${AP})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Carousels</span></>} sub="🧵 Voice Matched" visible={phase==="carousels"} color={AC}/>
      <PhaseLabel text={<>Content <span style={{background:`linear-gradient(135deg,${AR},${AP})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Calendar</span></>} sub="📅 Distribution Layer" visible={phase==="calendar"} color={AR}/>
      <PhaseLabel text={<>Follow Creators. <span style={{background:`linear-gradient(135deg,${AA},${AC})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>Repurpose Everything.</span></>} sub="🚀 Growth Hack" visible={phase==="repurpose"} color={AA}/>

      {/* MAIN STAGE */}
      <div style={{position:"relative",width:"600px",height:"380px",marginTop:"10px"}}>

        {/* 1. UPLOAD ICON */}
        {(phase==="upload"||phase==="processing")&&(
          <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-50%)",display:"flex",flexDirection:"column",alignItems:"center",gap:"14px",zIndex:40}}>
            <div style={{width:"90px",height:"90px",borderRadius:"22px",background:isProc?`linear-gradient(135deg,${AO}20,${AC}20)`:BC,border:`2px solid ${isProc?AO:AC}40`,display:"flex",alignItems:"center",justifyContent:"center",animation:phase==="upload"?"uploadBounce 0.6s ease infinite":"none",boxShadow:isProc?`0 0 40px ${AO}30`:"none",transition:"all 0.5s ease"}}>
              {isProc?<div style={{width:"36px",height:"36px",border:`3px solid ${AO}30`,borderTop:`3px solid ${AO}`,borderRadius:"50%",animation:"spin 0.8s linear infinite"}}/>:<span style={{fontSize:"32px"}}>⬆️</span>}
            </div>
            <ProgressBar progress={progress} visible={isProc}/>
            <div style={{fontSize:"11px",color:AO,fontWeight:500,opacity:isProc?1:0,transition:"opacity 0.3s ease",height:"14px"}}>{STEPS[stepIdx]}</div>
            {phase==="upload"&&<div style={{fontSize:"12px",color:"#64748b"}}>Drop any video to start</div>}
          </div>
        )}

        {/* 3. KNOWLEDGE BASE */}
        {phase==="kb"&&(
          <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-50%)",width:"300px",height:"300px"}}>
            {KB_SOURCES.map((s,i)=><KBNode key={s.label} source={s} index={i} visible={true} total={KB_SOURCES.length}/>)}
            <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-50%)",width:"70px",height:"70px",borderRadius:"50%",background:`radial-gradient(circle,${AC}20,${BD})`,border:`2px solid ${AC}40`,display:"flex",alignItems:"center",justifyContent:"center",animation:"corePulse 2s ease-in-out infinite",zIndex:5}}>
              <div style={{textAlign:"center"}}><div style={{fontSize:"18px"}}>🧠</div><div style={{fontSize:"8px",fontWeight:700,color:AC}}>YOUR VOICE</div></div>
            </div>
          </div>
        )}

        {/* 4. SCREENSHOTS */}
        <ScreenshotFrame src={IMG_HOME} visible={phase==="screenshots"} delay={0} width={280} x={-80} y={-10} borderColor={AO}/>
        <ScreenshotFrame src={IMG_CK} visible={phase==="screenshots"} delay={0.2} width={230} x={80} y={10} borderColor={AC}/>

        {/* 5. OUTPUT CARDS */}
        {OUTPUTS.map((item,i)=><OutputCard key={item.label} item={item} index={i} visible={phase==="outputs"} total={OUTPUTS.length}/>)}

        {/* 6. CAROUSEL SLIDES */}
        {SLIDES_IMG.map((img,i)=><SlideCard key={i} img={img} index={i} total={SLIDES_IMG.length} visible={phase==="carousels"}/>)}

        {/* 7. CALENDAR */}
        {phase==="calendar"&&(
          <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-50%)"}}>
            <MiniCal visible={true} revealCount={calReveal}/>
          </div>
        )}

        {/* 8. REPURPOSE */}
        {phase==="repurpose"&&(
          <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-50%)",display:"flex",flexDirection:"column",alignItems:"center",gap:"20px",animation:"fadeInUp 0.6s ease"}}>
            <div style={{display:"flex",gap:"10px",alignItems:"center"}}>
              {["🎯","🔥","🧘"].map((e,i)=>(
                <div key={i} style={{width:"50px",height:"50px",borderRadius:"50%",background:`${AA}15`,border:`1.5px solid ${AA}40`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"20px"}}>{e}</div>
              ))}
              <div style={{display:"flex",alignItems:"center",gap:"2px",margin:"0 8px"}}>
                {[0,1,2].map(i=><div key={i} style={{width:"6px",height:"2px",background:AC,borderRadius:"1px",opacity:1-i*0.2}}/>)}
                <div style={{width:0,height:0,borderTop:"4px solid transparent",borderBottom:"4px solid transparent",borderLeft:`6px solid ${AC}`}}/>
              </div>
              <div style={{width:"60px",height:"60px",borderRadius:"16px",background:`linear-gradient(135deg,${AC}20,${AP}20)`,border:`2px solid ${AC}50`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"24px",animation:"corePulse 2s ease-in-out infinite"}}>🧠</div>
              <div style={{display:"flex",alignItems:"center",gap:"2px",margin:"0 8px"}}>
                {[0,1,2].map(i=><div key={i} style={{width:"6px",height:"2px",background:AA,borderRadius:"1px",opacity:1-i*0.2}}/>)}
                <div style={{width:0,height:0,borderTop:"4px solid transparent",borderBottom:"4px solid transparent",borderLeft:`6px solid ${AA}`}}/>
              </div>
              <div style={{width:"50px",height:"50px",borderRadius:"14px",background:`${AA}15`,border:`1.5px solid ${AA}40`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"16px",fontWeight:700,color:AA}}>YOU</div>
            </div>
            <CreatorBadge visible={true}/>
          </div>
        )}

        {/* 9. CTA */}
        {phase==="cta"&&(
          <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-50%)",textAlign:"center",animation:"fadeInUp 0.6s ease"}}>
            <div style={{fontSize:"40px",marginBottom:"12px"}}>🔊</div>
            <h1 style={{fontSize:"32px",fontWeight:300,color:"#e2e8f0",margin:"0 0 8px",letterSpacing:"-0.5px"}}>
              <span style={{background:`linear-gradient(135deg,${AC},${AP})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",fontWeight:700}}>EchoMe</span>
            </h1>
            <p style={{fontSize:"15px",color:"#94a3b8",margin:"0 0 20px"}}>Your voice. Your content. Done.</p>
            <div style={{display:"inline-flex",alignItems:"center",gap:"8px",background:`${AC}15`,border:`1px solid ${AC}40`,borderRadius:"24px",padding:"10px 24px",fontSize:"14px",color:AC,fontWeight:600,letterSpacing:"0.3px"}}>tryechome.com</div>
          </div>
        )}
      </div>

      {/* BOTTOM PROGRESS DOTS */}
      <div style={{position:"absolute",bottom:"20px",display:"flex",gap:"8px",alignItems:"center"}}>
        {["upload","processing","kb","screenshots","outputs","carousels","calendar","repurpose","cta"].map((p,i)=>(
          <div key={p} style={{width:phase===p?"20px":"6px",height:"6px",borderRadius:"3px",background:phase===p?AC:`${AC}30`,transition:"all 0.3s ease"}}/>
        ))}
      </div>
    </div>
  );
}
